"""Append C206 (idempotent): in-band rank is noise, so it cannot be used to judge a thousandth-level change."""
import io, os

p = 'state/FACTS.md'
ADD = """| C206 | 📉 **【档内名次【不能】当成未取整分的代理 —— 它的波动是平台重评估噪声,幅度远超我们的改动】** 我原本打算用"我们自己名次的位移"来检验一千分之一级别的改动（因为显示分被钉死,只有未取整值还能差）。查 `state/daily_trend.jsonl` 之后这条路关闭。<br>**① 反证（逐条读数）**：<br>| 时间 | N | 我们的 rank |<br>|---|---|---|<br>| 10-16 12:42 | 6085 | **231** |<br>| 10-17 01:30 | 6113 | **419** |<br>| 10-17 13:24 | 6138 | **264** |<br>| 10-18 01:11 | 6158 | 305 |<br>| 10-19 01:17 | 6194 | 383 |<br>| 10-20 00:56 | 6241 | 458 |<br>**⇒ 10-16 12:42 → 10-17 01:30 之间,名次从 231 掉到 419（−188）,而**这段时间我们没有任何提交**,新参赛队只增加了 **28** 支 ⇒ **−188 不可能是膨胀造成的**。同样 10-17 01:30 → 13:24 又回升 +155（这段时间同样没有提交）。<br>**② ⇒ 最可能的机制**：这是 **code competition —— 提交的内核会被平台【重跑】评分**。若重跑有任何随機性（增强顺序、GPU 非确定性、worker 切分），**未取整分每次重跑都会变一点**,而在一个 1313 队同分的档里,一点点就值上百个名次。<br>**③ ⇒ 三条后果**：**(a)** "用名次检验改动"**不可行** —— 噪声 ±150 淹没一切;**(b)** **我们自己的分数也有重跑噪声**,所以"某次提交比另一次好 0.001"在原理上就无法从公榜分辨（与 C184 的 SE≈0.003 是同一件事的两种表现）;**(c)** **截止日的 tick 选择**本质上是在**同一分布里抽一次**,而不是在"已知更好"之间选 —— 这一条要写进截止日清单,免得那天误以为有确定性。<br>**④ 这次是"先设计了一个测量方案,又用数据把它否掉"** —— 比直接凭直觉用名次当信号好,但代价是这一步花了时间才认清无信号。**⇒ 方法论：设计代理指标时，先查该指标的历史波动幅度是否【大于】待测效应。** | 2026-10-20 |
"""

if '| C206 |' in io.open(p, encoding='utf-8').read():
    raise SystemExit('REFUSING: C206 is already present')
with io.open(p, 'a', encoding='utf-8') as fh:
    fh.write(ADD)
print('appended C206; file now', os.path.getsize(p), 'bytes')
